    const forRight=angle===90?'bottom':'top';   // 器の右 ← 端末の(下 / 上)
    const forTop=angle===90?'right':'left';     // 器の上 ← 端末の(右 / 左)
    const forBottom=angle===90?'left':'right';  // 器の下 ← 端末の(左 / 右)
