      [[2637,0],[3520,.04]].forEach(([f,at])=>[[1,.45,.06],[2.76,.15,.03]].forEach(([r,p,t])=>K.tone('sine',f*s*r,f*s*r,p,0,{at,attack:.0008,tau:t*L})));
