    grad.addColorStop(0,white?'rgba(255,255,255,.55)':`rgba(${rgb},.45)`);grad.addColorStop(1,`rgba(${rgb},0)`);
    c.strokeStyle=grad;c.lineWidth=(1.2+4*rand())*(1-u0*.8);
