          const g=ctx.createLinearGradient(0,cy-by,0,cy+by*.4);g.addColorStop(0,'rgba(224,231,255,1)');g.addColorStop(.5,'rgba(99,102,241,1)');g.addColorStop(1,'rgba(30,27,75,1)');
